import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"环境变量","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/configuration/env-vars.md","filePath":"zh/kimi-code-cli/configuration/env-vars.md"}`),a={name:`kimi-code-cli/configuration/env-vars.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to “环境变量”">​</a></h1><p>Kimi Code CLI 通过环境变量控制少数运行时行为——迁移数据目录、关闭遥测、不改配置文件临时切换模型。</p><div class="warning custom-block"><p class="custom-block-title">重要：API 密钥不在这里配置</p><p><code>KIMI_API_KEY</code>、<code>ANTHROPIC_API_KEY</code>、<code>OPENAI_API_KEY</code> 等密钥变量<strong>不会</strong>从 shell 环境变量自动读取。在终端里 <code>export KIMI_API_KEY=xxx</code> 不会让任何供应商获得密钥——必须写在 <code>config.toml</code> 的 <code>[providers.&lt;name&gt;]</code> 段或 <code>[providers.&lt;name&gt;.env]</code> 子表里。</p><p>唯一的例外是 <code>KIMI_MODEL_*</code> 系列，它是一个显式通道，<em>确实</em>会从 shell 读取凭证——详见<a href="#用环境变量定义模型-kimi-model">用环境变量定义模型</a>。</p><p>背景说明见<a href="/code/docs/kimi-code-cli/configuration/overrides.html#供应商凭证">配置覆盖：供应商凭证</a>。</p></div><h2 id="核心路径" tabindex="-1">核心路径 <a class="header-anchor" href="#核心路径" aria-label="Permalink to “核心路径”">​</a></h2><h3 id="kimi-code-home" tabindex="-1"><code>KIMI_CODE_HOME</code> <a class="header-anchor" href="#kimi-code-home" aria-label="Permalink to “KIMI_CODE_HOME”">​</a></h3><p>覆盖数据根目录，默认 <code>~/.kimi-code</code>。设置后，配置文件、会话、日志、OAuth 凭据等全部数据都落到新路径下：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_CODE_HOME</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/path/to/custom/kimi-code&quot;</span></span></code></pre></div><blockquote><p>确保目录可写。多个 <code>kimi</code> 实例共用同一个 <code>KIMI_CODE_HOME</code> 会共享配置和凭证。</p></blockquote><p>数据目录的完整结构见<a href="/code/docs/kimi-code-cli/configuration/data-locations.html">数据路径</a>。</p><h3 id="kimi-disable-telemetry" tabindex="-1"><code>KIMI_DISABLE_TELEMETRY</code> <a class="header-anchor" href="#kimi-disable-telemetry" aria-label="Permalink to “KIMI_DISABLE_TELEMETRY”">​</a></h3><p>设为 <code>1</code> 关闭匿名遥测上报（也接受 <code>true</code>/<code>yes</code>/<code>y</code>，不区分大小写）：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_DISABLE_TELEMETRY</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><h3 id="kimi-model-系列" tabindex="-1"><code>KIMI_MODEL_*</code> 系列 <a class="header-anchor" href="#kimi-model-系列" aria-label="Permalink to “KIMI_MODEL_* 系列”">​</a></h3><p>不修改 <code>config.toml</code> 临时切换模型——设置 <code>KIMI_MODEL_NAME</code> 后，CLI 在内存里合成一个临时供应商，重启后失效。详见<a href="#用环境变量定义模型kimi-model">用环境变量定义模型</a>。</p><h2 id="供应商凭证键-写在-config-toml-里" tabindex="-1">供应商凭证键（写在 config.toml 里） <a class="header-anchor" href="#供应商凭证键-写在-config-toml-里" aria-label="Permalink to “供应商凭证键（写在 config.toml 里）”">​</a></h2><p>下面这些键名不是直接从 shell 读取的——它们是写在 <code>config.toml</code> 的 <code>[providers.&lt;name&gt;.env]</code> 子表里、作为 <code>api_key</code> / <code>base_url</code> 备用来源的键名。CLI 只从配置文件读取，不从 <code>process.env</code> 读取。</p><p>这样设计是为了让你保留熟悉的键名写法，同时把密钥放在配置文件里统一管理：</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KIMI_API_KEY = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-xxx&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KIMI_BASE_URL = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.moonshot.ai/v1&quot;</span></span></code></pre></div><p>各供应商对应的键名：</p><table tabindex="0"><thead><tr><th>键名</th><th>适用供应商</th><th>默认值</th></tr></thead><tbody><tr><td><code>KIMI_API_KEY</code></td><td>Kimi / Moonshot</td><td>无</td></tr><tr><td><code>KIMI_BASE_URL</code></td><td>Kimi / Moonshot</td><td><code>https://api.moonshot.ai/v1</code></td></tr><tr><td><code>ANTHROPIC_API_KEY</code></td><td>Anthropic</td><td>无</td></tr><tr><td><code>ANTHROPIC_BASE_URL</code></td><td>Anthropic</td><td>Anthropic SDK 默认值</td></tr><tr><td><code>OPENAI_API_KEY</code></td><td>OpenAI（<code>openai</code> 和 <code>openai_responses</code>）</td><td>无</td></tr><tr><td><code>OPENAI_BASE_URL</code></td><td>OpenAI（<code>openai</code> 和 <code>openai_responses</code>）</td><td><code>https://api.openai.com/v1</code></td></tr><tr><td><code>GOOGLE_API_KEY</code></td><td>Google GenAI、Vertex AI</td><td>无</td></tr><tr><td><code>VERTEXAI_API_KEY</code></td><td>Vertex AI</td><td>无</td></tr><tr><td><code>GOOGLE_CLOUD_PROJECT</code></td><td>Vertex AI</td><td>无</td></tr><tr><td><code>GOOGLE_CLOUD_LOCATION</code></td><td>Vertex AI</td><td>无</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p><code>GOOGLE_APPLICATION_CREDENTIALS</code>（服务账号 JSON 路径）是唯一走系统环境变量的例外——它由 Google SDK 自身通过 ADC 流程读取，CLI 不参与。其他所有键名都必须写在 <code>[providers.&lt;name&gt;.env]</code> 子表里。</p></div><p>供应商类型与字段的完整说明见<a href="/code/docs/kimi-code-cli/configuration/providers.html">平台与模型</a>。</p><h2 id="oauth-与托管端点" tabindex="-1">OAuth 与托管端点 <a class="header-anchor" href="#oauth-与托管端点" aria-label="Permalink to “OAuth 与托管端点”">​</a></h2><p>这组变量用于将 OAuth 认证和托管服务端点指向自建或测试环境，日常使用不需要设置。</p><table tabindex="0"><thead><tr><th>环境变量</th><th>用途</th><th>默认值</th></tr></thead><tbody><tr><td><code>KIMI_CODE_OAUTH_HOST</code></td><td>OAuth 认证 host，优先级最高</td><td>未设时回退到 <code>KIMI_OAUTH_HOST</code></td></tr><tr><td><code>KIMI_OAUTH_HOST</code></td><td>OAuth 认证 host，作为上一个的 fallback</td><td>未设时使用 <code>https://auth.kimi.com</code></td></tr><tr><td><code>KIMI_CODE_BASE_URL</code></td><td>OAuth 登录后的托管 API base URL</td><td><code>https://api.kimi.com/coding/v1</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p><code>KIMI_CODE_BASE_URL</code>（OAuth 托管服务，指向 <code>kimi.com</code>）和 <code>KIMI_BASE_URL</code>（API 密钥直连，指向 <code>moonshot.ai</code>）是两个不同的变量，请按场景区分。</p></div><h2 id="用环境变量定义模型-kimi-model" tabindex="-1">用环境变量定义模型（<code>KIMI_MODEL_*</code>） <a class="header-anchor" href="#用环境变量定义模型-kimi-model" aria-label="Permalink to “用环境变量定义模型（KIMI_MODEL_*）”">​</a></h2><p>测试时想换个模型但不想动 <code>config.toml</code>？设置 <code>KIMI_MODEL_NAME</code> 后，CLI 会从 <code>KIMI_MODEL_*</code> 系列变量在内存里合成出一个临时供应商和模型别名，不写回配置文件。优先级高于 <code>config.toml</code> 的 <code>default_model</code>，但低于启动时 <code>-m &lt;alias&gt;</code> 选项。</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_MODEL_NAME</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;kimi-for-coding&quot;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_MODEL_API_KEY</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_API_KEY&quot;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_MODEL_BASE_URL</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.example.com/v1&quot;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_MODEL_MAX_CONTEXT_SIZE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;262144&quot;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_MODEL_CAPABILITIES</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;image_in,thinking&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span></span></code></pre></div><p>完整变量列表：</p><table tabindex="0"><thead><tr><th>环境变量</th><th>必填</th><th>用途</th><th>默认值</th></tr></thead><tbody><tr><td><code>KIMI_MODEL_NAME</code></td><td>是（同时是启用开关）</td><td>发送给 API 的模型 ID</td><td>—</td></tr><tr><td><code>KIMI_MODEL_API_KEY</code></td><td>是</td><td>API 密钥</td><td>—</td></tr><tr><td><code>KIMI_MODEL_PROVIDER_TYPE</code></td><td>否</td><td>供应商类型：<code>kimi</code>、<code>anthropic</code>、<code>openai</code></td><td><code>kimi</code></td></tr><tr><td><code>KIMI_MODEL_BASE_URL</code></td><td>否</td><td>API 基础 URL</td><td>各类型有各自默认值</td></tr><tr><td><code>KIMI_MODEL_MAX_CONTEXT_SIZE</code></td><td>否</td><td>最大上下文长度（token 数）</td><td><code>262144</code>（256K）</td></tr><tr><td><code>KIMI_MODEL_CAPABILITIES</code></td><td>否</td><td>逗号分隔的能力标签，与自动探测的能力取并集</td><td><code>image_in,thinking</code></td></tr><tr><td><code>KIMI_MODEL_DISPLAY_NAME</code></td><td>否</td><td>在 <code>/model</code> 中显示的名称</td><td>回退到 <code>KIMI_MODEL_NAME</code></td></tr><tr><td><code>KIMI_MODEL_MAX_OUTPUT_SIZE</code></td><td>否</td><td>单次输出上限（仅 <code>anthropic</code>）；设置后会覆盖内置的 Claude 上限</td><td>模型默认值</td></tr><tr><td><code>KIMI_MODEL_REASONING_KEY</code></td><td>否</td><td>推理字段名覆盖（仅 <code>openai</code>）</td><td>自动探测</td></tr><tr><td><code>KIMI_MODEL_THINKING_EFFORT</code></td><td>否</td><td>Thinking 强度：<code>low</code>/<code>medium</code>/<code>high</code>/<code>xhigh</code>/<code>max</code></td><td>—</td></tr><tr><td><code>KIMI_MODEL_ADAPTIVE_THINKING</code></td><td>否</td><td>强制开启或关闭 adaptive thinking（仅 <code>anthropic</code>）</td><td>按模型名推断</td></tr></tbody></table><p>设置了 <code>KIMI_MODEL_NAME</code> 但缺少必填变量时，启动会立即失败并给出明确提示。</p><h2 id="运行时开关" tabindex="-1">运行时开关 <a class="header-anchor" href="#运行时开关" aria-label="Permalink to “运行时开关”">​</a></h2><p>控制遥测、后台任务、plugin marketplace 等子系统行为的开关变量：</p><table tabindex="0"><thead><tr><th>环境变量</th><th>用途</th><th>合法值</th></tr></thead><tbody><tr><td><code>KIMI_DISABLE_TELEMETRY</code></td><td>关闭匿名遥测上报</td><td><code>1</code>、<code>true</code>、<code>yes</code>、<code>y</code>（不区分大小写）</td></tr><tr><td><code>KIMI_CODE_BACKGROUND_KEEP_ALIVE_ON_EXIT</code></td><td>会话关闭时是否保留后台任务，优先级高于 <code>config.toml</code>。默认会在退出时停止后台任务</td><td>真值：<code>1</code>/<code>true</code>/<code>yes</code>/<code>on</code>；假值：<code>0</code>/<code>false</code>/<code>no</code>/<code>off</code></td></tr><tr><td><code>KIMI_CODE_BACKGROUND_MAX_RUNNING_TASKS</code></td><td>同时运行的后台任务数上限，优先级高于 <code>config.toml</code> 的 <code>[background] max_running_tasks</code>（不设置表示无上限）</td><td>正整数；非法值被忽略</td></tr><tr><td><code>KIMI_IMAGE_MAX_EDGE_PX</code></td><td>图片压缩的最长边上限（像素），优先级高于 <code>config.toml</code> 的 <code>[image] max_edge_px</code>（默认 <code>2000</code>）</td><td>正整数；非法值被忽略</td></tr><tr><td><code>KIMI_IMAGE_READ_BYTE_BUDGET</code></td><td>模型自行读图（<code>ReadMediaFile</code> 默认读取）的单图字节预算，优先级高于 <code>config.toml</code> 的 <code>[image] read_byte_budget</code>（默认 <code>262144</code>，即 256 KB）</td><td>正整数；非法值被忽略</td></tr><tr><td><code>KIMI_CODE_PLUGIN_MARKETPLACE_URL</code></td><td>覆盖 <code>/plugins</code> 加载的 plugin marketplace JSON，适合 dev loopback server、测试 CDN 文件或替换 marketplace 目录</td><td><code>https://code.kimi.com/kimi-code/plugins/marketplace.json</code>；也接受 <code>http://</code>、<code>file://</code> URL 和本地路径</td></tr><tr><td><code>KIMI_CODE_AGENT_SWARM_MAX_CONCURRENCY</code></td><td>限制 AgentSwarm 初始提升并发阶段可同时运行的子 Agent 数量；不设置表示不限制</td><td>正整数；非法值会立即失败</td></tr><tr><td><code>KIMI_SUBAGENT_TIMEOUT_MS</code></td><td>单个子 Agent（<code>Agent</code> / <code>AgentSwarm</code>）可运行的最长时间（毫秒）；优先级高于 <code>config.toml</code> 的 <code>[subagent] timeout_ms</code>（默认 <code>7200000</code>，即 2 小时）</td><td>正整数；非法值回退到配置或默认值</td></tr><tr><td><code>KIMI_CODE_EXPERIMENTAL_SECONDARY_MODEL</code></td><td>在 <code>kimi web</code> 下启用实验性的次主力模型功能；<code>kimi -p</code> 仍需通过 <code>KIMI_CODE_EXPERIMENTAL_FLAG=1</code> 选择 v2 引擎，该 master flag 也会启用本功能</td><td>真值：<code>1</code>/<code>true</code>/<code>yes</code>/<code>on</code>；假值：<code>0</code>/<code>false</code>/<code>no</code>/<code>off</code></td></tr><tr><td><code>KIMI_SECONDARY_MODEL</code></td><td>次主力模型；优先级高于 <code>config.toml</code> 的 <code>[secondary_model] model</code>。次主力模型实验功能启用后，新派生的子 Agent 默认绑定该模型，而不再继承主 Agent 的模型（TUI 不支持）</td><td>已配置 <code>[models]</code> 中的模型 id，如 <code>kimi-code/kimi-k2.5</code>；空白值被忽略</td></tr><tr><td><code>KIMI_SECONDARY_EFFORT</code></td><td>次主力模型的 thinking effort；优先级高于 <code>config.toml</code> 的 <code>[secondary_model] default_effort</code>，仅在次主力模型及其实验功能均启用时生效（TUI 不支持）</td><td>effort 取值，如 <code>low</code>；空白值被忽略</td></tr><tr><td><code>KIMI_MCP_STARTUP_TIMEOUT_MS</code></td><td>所有 MCP server 的全局默认连接超时（毫秒）；优先级高于 <code>config.toml</code> 的 <code>[mcp] startup_timeout_ms</code>，但低于 <code>mcp.json</code> 中单个 server 的 <code>startupTimeoutMs</code>（默认 <code>30000</code>）</td><td><code>1</code> 到 <code>2147483647</code> 的整数；非法值被忽略</td></tr><tr><td><code>KIMI_MCP_TOOL_TIMEOUT_MS</code></td><td>所有 MCP server 的全局默认单次工具调用超时（毫秒）；优先级高于 <code>config.toml</code> 的 <code>[mcp] tool_timeout_ms</code>，但低于 <code>mcp.json</code> 中单个 server 的 <code>toolTimeoutMs</code>（默认 <code>60000</code>）</td><td><code>1</code> 到 <code>2147483647</code> 的整数；非法值被忽略</td></tr><tr><td><code>KIMI_LOOP_MAX_STEPS_PER_TURN</code></td><td>Agent 单轮最大步数；优先级高于 <code>config.toml</code> 的 <code>[loop_control] max_steps_per_turn</code>（不设或 <code>0</code> 表示无上限）</td><td>非负整数；非法值被忽略</td></tr><tr><td><code>KIMI_LOOP_MAX_RETRIES_PER_STEP</code></td><td>单步失败后的最大重试次数；优先级高于 <code>config.toml</code> 的 <code>[loop_control] max_retries_per_step</code>（默认 <code>10</code>）</td><td>非负整数；非法值被忽略</td></tr><tr><td><code>KIMI_WEB_SEARCH_BASE_URL</code></td><td>网页搜索（<code>WebSearch</code>）服务的 API URL；优先级高于 <code>config.toml</code> 的 <code>[services.moonshot_search] base_url</code>，未写配置段时也可启用服务。文件中持久化的凭据和自定义 header 不会发送到环境变量指定的端点</td><td>非空字符串；空白值被忽略</td></tr><tr><td><code>KIMI_WEB_SEARCH_API_KEY</code></td><td>网页搜索（<code>WebSearch</code>）服务的 API 密钥；设置后同时替换配置中的 API 密钥和 OAuth 凭据</td><td>非空字符串；空白值被忽略</td></tr><tr><td><code>KIMI_WEB_FETCH_BASE_URL</code></td><td>网页抓取（<code>FetchURL</code>）服务的 API URL；优先级高于 <code>[services.moonshot_fetch] base_url</code>。文件中持久化的凭据和自定义 header 不会发送到环境变量指定的端点。环境变量和配置都没有指定端点时，已登录用户会先尝试 Kimi OAuth 托管抓取服务，再回退到本地直接请求</td><td>非空字符串；空白值被忽略</td></tr><tr><td><code>KIMI_WEB_FETCH_API_KEY</code></td><td>网页抓取（<code>FetchURL</code>）服务的 API 密钥；设置后同时替换配置中的 API 密钥和 OAuth 凭据</td><td>非空字符串；空白值被忽略</td></tr><tr><td><code>KIMI_CODE_EXPERIMENTAL_FLAG</code></td><td>在当前进程启用所有已注册的实验功能</td><td><code>1</code>、<code>true</code>、<code>yes</code>、<code>on</code></td></tr><tr><td><code>KIMI_SHELL_PATH</code></td><td>Windows 上覆盖 Git Bash 路径（自动探测失败时使用）</td><td>绝对路径</td></tr><tr><td><code>KIMI_MODEL_MAX_COMPLETION_TOKENS</code></td><td>单步 LLM 请求的 <code>max_completion_tokens</code> 硬上限，仅对 <code>kimi</code> 供应商生效</td><td>正整数；<code>0</code> 或负数禁用 clamp</td></tr><tr><td><code>KIMI_MODEL_TEMPERATURE</code></td><td>每次请求的采样温度，仅对 <code>kimi</code> 供应商生效（全局生效，不依赖 <code>KIMI_MODEL_NAME</code>）</td><td>数字，如 <code>0.3</code></td></tr><tr><td><code>KIMI_MODEL_TOP_P</code></td><td>每次请求的核采样 <code>top_p</code>，仅对 <code>kimi</code> 供应商生效（全局生效）</td><td>数字，如 <code>0.95</code></td></tr><tr><td><code>KIMI_MODEL_THINKING_EFFORT</code></td><td>在线上强制使用指定的思考强度（<code>thinking.effort</code>），绕过模型声明的 <code>support_efforts</code>；仅对 <code>kimi</code> 供应商生效，且仅在 Thinking 开启时注入</td><td>思考强度值，如 <code>max</code></td></tr><tr><td><code>KIMI_MODEL_THINKING_KEEP</code></td><td>保留思考透传；在 <code>kimi</code> 上以 <code>thinking.keep</code> 发送，在 <code>anthropic</code>（Claude 以及 Kimi 的 Anthropic 兼容模式）上以 <code>context_management</code> 的 <code>clear_thinking_20251015</code> 编辑发送（开启 keep 会让 Anthropic 请求走 beta Messages API）；覆盖 <code>[thinking] keep</code>（其默认值为 <code>&quot;all&quot;</code>）；仅在 Thinking 开启时注入</td><td>API 接受的值，如 <code>all</code>；传入关值（<code>false</code>/<code>0</code>/<code>no</code>/<code>off</code>/<code>none</code>/<code>null</code>）可禁用</td></tr><tr><td><code>KIMI_CODE_NO_AUTO_UPDATE</code></td><td>完全禁用更新预检——不检查、不后台安装、不提示。同时兼容旧名 <code>KIMI_CLI_NO_AUTO_UPDATE</code></td><td>真值：<code>1</code>/<code>true</code>/<code>yes</code>/<code>on</code></td></tr><tr><td><code>KIMI_DISABLE_CRON</code></td><td>禁用定时任务工具（<code>CronCreate</code> 拒绝新计划，已有任务不触发）</td><td><code>1</code> 表示禁用</td></tr></tbody></table><h2 id="诊断日志" tabindex="-1">诊断日志 <a class="header-anchor" href="#诊断日志" aria-label="Permalink to “诊断日志”">​</a></h2><p>这组变量控制日志级别和文件滚动，进程启动时读取一次：</p><table tabindex="0"><thead><tr><th>环境变量</th><th>用途</th><th>默认值</th></tr></thead><tbody><tr><td><code>KIMI_LOG_LEVEL</code></td><td>日志级别：<code>off</code>、<code>error</code>、<code>warn</code>、<code>info</code>、<code>debug</code></td><td><code>info</code></td></tr><tr><td><code>KIMI_LOG_GLOBAL_MAX_BYTES</code></td><td>全局日志文件单个最大字节数</td><td><code>6291456</code>（6 MB）</td></tr><tr><td><code>KIMI_LOG_GLOBAL_FILES</code></td><td>全局日志文件保留份数</td><td><code>5</code></td></tr><tr><td><code>KIMI_LOG_SESSION_MAX_BYTES</code></td><td>会话级日志文件单个最大字节数</td><td><code>5242880</code>（5 MB）</td></tr><tr><td><code>KIMI_LOG_SESSION_FILES</code></td><td>会话级日志文件保留份数</td><td><code>3</code></td></tr></tbody></table><h2 id="系统环境变量" tabindex="-1">系统环境变量 <a class="header-anchor" href="#系统环境变量" aria-label="Permalink to “系统环境变量”">​</a></h2><p>CLI 还会读取一些标准系统变量来检测运行环境，不会修改它们：</p><ul><li><code>HOME</code>：解析默认数据路径</li><li><code>VISUAL</code>、<code>EDITOR</code>：外部编辑器命令（<code>VISUAL</code> 优先）</li><li><code>PATH</code>：定位 <code>rg</code>、<code>fd</code>、<code>fdfind</code>、<code>git</code> 等依赖；在 Windows 上，Git Bash 探测会检查 <code>PATH</code> 中找到的每个 <code>git.exe</code>，包括 Scoop 等包管理器提供的 shim</li><li><code>NO_COLOR</code>、<code>FORCE_COLOR</code>：控制颜色输出（遵循 <a href="https://no-color.org" target="_blank" rel="noreferrer">no-color.org</a> 约定）</li><li><code>CI</code>：非空且非 <code>&quot;0&quot;</code> 时关闭主题检测，回退深色主题</li><li><code>TERM_PROGRAM</code>、<code>TERM</code>、<code>TMUX</code>：检测终端特性和通知支持</li><li><code>DISPLAY</code>、<code>WAYLAND_DISPLAY</code>、<code>XDG_SESSION_TYPE</code>：检测 Linux 图形会话（用于剪贴板和图片功能）</li><li><code>WSL_DISTRO_NAME</code>、<code>WSLENV</code>：检测 WSL，用于剪贴板 PowerShell 桥接</li><li><code>LOCALAPPDATA</code>：Windows 上探测 Git Bash 安装路径时作为 fallback 使用</li></ul><h2 id="http-代理" tabindex="-1">HTTP 代理 <a class="header-anchor" href="#http-代理" aria-label="Permalink to “HTTP 代理”">​</a></h2><p>Kimi Code 会遵循标准代理环境变量，让所有出网流量——模型 API 调用、MCP 服务、网络工具、遥测、登录、更新检查——都走代理：</p><ul><li><code>HTTP_PROXY</code> / <code>http_proxy</code>：用于 <code>http://</code> 请求的代理</li><li><code>HTTPS_PROXY</code> / <code>https_proxy</code>：用于 <code>https://</code> 请求的代理</li><li><code>ALL_PROXY</code> / <code>all_proxy</code>：当对应 scheme 的变量未设置时使用的兜底代理；SOCKS 代理通常设在这里</li><li><code>NO_PROXY</code> / <code>no_proxy</code>：以逗号分隔的、绕过代理的主机列表</li></ul><p>同时支持 HTTP(S) 代理和 SOCKS 代理。SOCKS 代理通过 scheme 识别——<code>socks5://</code>、<code>socks5h://</code>、<code>socks4://</code> 或 <code>socks://</code>（<code>socks5://</code> 的别名）——通常设在 <code>ALL_PROXY</code>（Clash、V2RayN 等工具使用的形式）。对 HTTP/HTTPS 流量，HTTP(S) 代理优先于 <code>ALL_PROXY</code>。</p><p>仅当设置了其中任一变量时才启用代理，否则直连。回环地址（<code>localhost</code>、<code>127.0.0.1</code>、<code>::1</code>）始终绕过代理，因此配置了代理后，本地服务（例如 localhost 上的 MCP 服务）仍能正常工作——你也可以把自己的内网主机加入 <code>NO_PROXY</code> 一并放行。</p><p>以 Node 子进程运行的 stdio MCP 服务，在其 Node 版本支持 <code>NODE_USE_ENV_PROXY</code> 时（Node ≥ 22.21 或 ≥ 24.5）会自动遵循 <code>HTTP_PROXY</code> / <code>HTTPS_PROXY</code> / <code>NO_PROXY</code>；SOCKS 代理仅作用于 Kimi Code 自身的流量。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/configuration/overrides.html">配置覆盖</a> — 环境变量、CLI 选项、配置文件的优先级关系</li><li><a href="/code/docs/kimi-code-cli/configuration/data-locations.html">数据路径</a> — <code>KIMI_CODE_HOME</code> 影响的完整目录结构</li><li><a href="/code/docs/kimi-code-cli/configuration/providers.html">平台与模型</a> — 各供应商类型的完整接入示例</li></ul>`,49)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};